#include <stdio.h>

void convert(int minutes, int *h, int *m)     /* no global variables used */
{
    *h = minutes / 60;
    *m = minutes % 60;
}

int main(void)
{
    int h, m;
    convert(135, &h, &m);
    printf("135 minutes = %d h %d min\n", h, m);
    return 0;
}

