/* returns a mod b using repeated subtraction; no global variables */
int remainderOf(int a, int b)
{
    while (a >= b)
    {
        a -= b;
    }
    return a;
}

int main(void)
{
    int a = 100, b = 7;
    printf("%d mod %d = %d\n", a, b, remainderOf(a, b));
    a = 5; b = 9;
    printf("%d mod %d = %d\n", a, b, remainderOf(a, b));
    return 0;
}

