            printf("Invalid side.\n");
            return 1;
        }
    }
    /* loop finds the longest side and adds squares of the other two */
    largest = s[0];
    for (i = 1; i < 3; i++)
        if (s[i] > largest) { largest = s[i]; big = i; }
    for (i = 0; i < 3; i++)
        if (i != big) sumSquares += s[i] * s[i];

    printf("%g^2 = %g, other squares sum = %g\n", largest, largest * largest, sumSquares);
    printf("%s\n", sumSquares == largest * largest ? "Right-angled triangle." : "Not right-angled.");
    return 0;
}

