#include <stdio.h>
#define MAX 5

int main(void)
{
    int stack[MAX], top = -1, choice, value, i;
    do
    {
        printf("\n1. Push\n2. Pop\n3. Peek\n4. Display\n5. Exit\n");
        printf("Enter choice: ");
        scanf("%d", &choice);
        switch (choice)
        {
            case 1:
                if (top == MAX - 1)
                    printf("Stack overflow!\n");
                else
                {
                    printf("Enter value: ");
                    scanf("%d", &value);
                    stack[++top] = value;
                    printf("%d pushed.\n", value);
                }
                break;
            case 2:
                if (top == -1)
                    printf("Stack underflow!\n");
                else
                    printf("Popped %d\n", stack[top--]);
                break;
            case 3:
                if (top == -1)
                    printf("Stack is empty.\n");
                else
                    printf("Top element = %d\n", stack[top]);
                break;
            case 4:
                if (top == -1)
                    printf("Stack is empty.\n");
                else
                {
                    printf("Stack (top to bottom):");
                    for (i = top; i >= 0; i--)
                        printf(" %d", stack[i]);
                    printf("\n");
                }
                break;
            case 5:
                printf("Exiting.\n");
                break;
            default:
                printf("Invalid choice.\n");
        }
    } while (choice != 5);
    return 0;
}

