/* results are returned through pointers */
void interest(double p, double r, double t, double *si, double *ci)
{
    *si = p * r * t / 100.0;
    *ci = p * pow(1 + r / 100.0, t) - p;
}

int main(void)
{
    int choice;
    double p, r, t, si, ci;

    printf("1. Simple interest\n2. Compound interest\nChoice: ");
