        printf("Invalid choice.\n");
        return 0;
    }
    printf("Enter principal, rate(%%) and time(years): ");
    if (scanf("%lf %lf %lf", &p, &r, &t) != 3)
        return 1;

    interest(p, r, t, &si, &ci);
    if (choice == 1)
        printf("Simple interest   = %.2f\n", si);
    else
        printf("Compound interest = %.2f (amount %.2f)\n", ci, p + ci);
    return 0;
}

