/* writes digits of n in the given base into buf, returns the text */
char *toBase(unsigned int n, int base, char *buf)
{
    const char *digits = "0123456789ABCDEF";
    char tmp[40];
    int len = 0, i = 0;

    do {
        tmp[len++] = digits[n % (unsigned)base];
        n /= (unsigned)base;
    } while (n > 0);
    while (len > 0)
        buf[i++] = tmp[--len];
    buf[i] = '\0';
    return buf;
}

