    /* digit at position p (from the left) is raised to power p */
    position = digits;
    for (temp = n; temp > 0; temp /= 10)
    {
        digit = temp % 10;
        power = 1;
        for (i = 0; i < position; i++)
            power *= digit;
        sum += power;
        position--;
    }
    printf("Sum of digits powered by position = %d\n", sum);
    if (n > 0 && sum == n)
        printf("%d is a Disarium number.\n", n);
