int main(void)
{
    long long n, first, power = 1, middle, result;
    int last;

    printf("Enter a positive integer: ");
    if (scanf("%lld", &n) != 1 || n <= 0) {
        printf("Invalid input.\n");
        return 1;
    }
    last = n % 10;
    first = n;
    while (first >= 10) {
        first /= 10;
        power *= 10;                 /* power = 10^(digits-1) */
    }
    if (power == 1) {
        result = n;                  /* single digit: nothing to swap */
    } else {
        middle = (n % power) / 10;   /* digits between first and last */
        result = last * power + middle * 10 + first;
    }
    printf("After swapping: %lld\n", result);
    return 0;
}

