int main(void)
{
    long long a, b, sum = 0, place = 1;
    long long x, y;
    int carry = 0;

    printf("Enter two binary numbers: ");
    if (scanf("%lld %lld", &a, &b) != 2 || a < 0 || b < 0) return 1;
    x = a;
    y = b;
    while (x > 0 || y > 0 || carry) {
        int bitA = x % 10, bitB = y % 10;
        int total = bitA + bitB + carry;
        if (bitA > 1 || bitB > 1) {
            printf("Invalid binary number.\n");
            return 1;
        }
        sum += (total % 2) * place;  /* result bit */
        carry = total / 2;           /* carry to next position */
        place *= 10;
        x /= 10;
        y /= 10;
    }
    printf("%lld + %lld = %lld (binary)\n", a, b, sum);
    return 0;
}

