#include <stdio.h>
#define MAX 100

/* reverse a[from..to] */
void reverse(int a[], int from, int to)
{
    int t;
    while (from < to) {
        t = a[from];
        a[from] = a[to];
        a[to] = t;
        from++;
        to--;
    }
}

