int main(void)
{
    int a[] = {4, 6, 2, 4, 6, 4, 9, 2};
    int n = sizeof(a) / sizeof(a[0]);
    int value[10], freq[10], m = 0;
    int i, j, found, t;

    /* build table of distinct values with their counts */
    for (i = 0; i < n; i++)
    {
        found = 0;
        for (j = 0; j < m; j++)
        {
            if (value[j] == a[i])
            {
                freq[j]++;
                found = 1;
                break;
            }
        }
        if (!found)
        {
            value[m] = a[i];
            freq[m] = 1;
            m++;
        }
    }

    /* sort table by frequency (high first); equal frequency keeps first-seen order */
    for (i = 1; i < m; i++)
    {
        int v = value[i], f = freq[i];
        j = i - 1;
        while (j >= 0 && freq[j] < f)
        {
            value[j + 1] = value[j];
            freq[j + 1] = freq[j];
            j--;
        }
        value[j + 1] = v;
        freq[j + 1] = f;
    }

    printf("Original: ");
    for (i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\nSorted by frequency: ");
    for (i = 0; i < m; i++)
        for (t = 0; t < freq[i]; t++)
            printf("%d ", value[i]);
    printf("\n");
    return 0;
}

