        {
            a[j + 1] = a[j];
            j--;
        }
        a[j + 1] = temp;
    }

    printf("After : ");
    for (i = 0; i < n; i++)
        printf("%d%c ", a[i].key, a[i].tag);
    printf("\n(equal keys keep their original order: 1b before 1e, 3a 3c 3f)\n");
