int main(void)
{
    int base[] = {9, 4, 7, 1, 8, 2, 6};
    int n = sizeof(base) / sizeof(base[0]);
    int a[7], i, j, min, temp;
    int bubbleCmp = 0, selCmp = 0;

    /* bubble sort on a copy */
    for (i = 0; i < n; i++)
        a[i] = base[i];
    for (i = 0; i < n - 1; i++)
    {
        for (j = 0; j < n - 1 - i; j++)
        {
            bubbleCmp++;
            if (a[j] > a[j + 1])
            {
                temp = a[j]; a[j] = a[j + 1]; a[j + 1] = temp;
            }
        }
    }

    /* selection sort on a fresh copy */
    for (i = 0; i < n; i++)
        a[i] = base[i];
    for (i = 0; i < n - 1; i++)
    {
        min = i;
        for (j = i + 1; j < n; j++)
        {
            selCmp++;
            if (a[j] < a[min])
                min = j;
        }
        temp = a[i]; a[i] = a[min]; a[min] = temp;
    }

    printf("Array size          : %d\n", n);
    printf("Bubble sort compares: %d\n", bubbleCmp);
    printf("Selection sort compares: %d\n", selCmp);
    printf("Both need n(n-1)/2 = %d comparisons here.\n", n * (n - 1) / 2);
    return 0;
}

