        if (scanf("%d %d %d", &d[i].day, &d[i].month, &d[i].year) != 3) { printf("Invalid date\n"); return 1; }

    for (i = 1; i < n; i++) {            /* insertion sort */
        key = d[i];
        for (j = i - 1; j >= 0 && compare(d[j], key) > 0; j--)
            d[j + 1] = d[j];
        d[j + 1] = key;
    }
    printf("Sorted dates:\n");
    for (i = 0; i < n; i++)
        printf("%02d-%02d-%04d\n", d[i].day, d[i].month, d[i].year);
