#define MAX 20

/* merge a[lo..mid] and a[mid+1..hi]; asc = 1 for ascending, 0 for descending */
void merge(int a[], int lo, int mid, int hi, int asc)
{
    int tmp[MAX], i = lo, j = mid + 1, k = lo;
    while (i <= mid && j <= hi) {
        if (asc ? a[i] <= a[j] : a[i] >= a[j]) tmp[k++] = a[i++];
        else tmp[k++] = a[j++];
    }
    while (i <= mid) tmp[k++] = a[i++];
    while (j <= hi) tmp[k++] = a[j++];
    for (k = lo; k <= hi; k++) a[k] = tmp[k];
}

void merge_sort(int a[], int lo, int hi, int asc)
{
    int mid;
    if (lo >= hi) return;
    mid = (lo + hi) / 2;
    merge_sort(a, lo, mid, asc);
    merge_sort(a, mid + 1, hi, asc);
    merge(a, lo, mid, hi, asc);
}

int main(void)
{
    int orig[MAX], a[MAX], n, i, choice;

    printf("Enter n and the elements: ");
    if (scanf("%d", &n) != 1 || n < 1 || n > MAX) { printf("Invalid size\n"); return 1; }
    for (i = 0; i < n; i++) scanf("%d", &orig[i]);

    do {
        printf("\n1. Merge sort ascending\n2. Merge sort descending\n3. Exit\nChoice: ");
        if (scanf("%d", &choice) != 1) break;
        if (choice == 1 || choice == 2) {
            for (i = 0; i < n; i++) a[i] = orig[i];
            merge_sort(a, 0, n - 1, choice == 1);
            printf("Result:");
            for (i = 0; i < n; i++) printf(" %d", a[i]);
            printf("\n");
        } else if (choice != 3) {
            printf("Invalid choice\n");
        }
    } while (choice != 3);
    return 0;
}

