int partition(int a[], int lo, int hi, int n)
{
    int pivot = a[hi], i = lo - 1, j, t;
    for (j = lo; j < hi; j++)
        if (a[j] < pivot) {
            i++;
            t = a[i]; a[i] = a[j]; a[j] = t;
        }
    t = a[i + 1]; a[i + 1] = a[hi]; a[hi] = t;
    printf("Pivot %2d placed at index %d : ", pivot, i + 1);
    print_array(a, n);                      /* intermediate step */
    return i + 1;
}

void quick_sort(int a[], int lo, int hi, int n)
{
    int p;
    if (lo < hi) {
        p = partition(a, lo, hi, n);
        quick_sort(a, lo, p - 1, n);
        quick_sort(a, p + 1, hi, n);
    }
}

