#include <stdio.h>

/* push a[i] down so the subtree rooted at i is a max-heap */
void heapify(int a[], int n, int i)
{
    int largest, l, r, t;
    while (1) {
        largest = i; l = 2 * i + 1; r = 2 * i + 2;
        if (l < n && a[l] > a[largest]) largest = l;
        if (r < n && a[r] > a[largest]) largest = r;
        if (largest == i) break;
        t = a[i]; a[i] = a[largest]; a[largest] = t;
        i = largest;
    }
}

int main(void)
{
    int a[20], n, i, t;

    printf("Enter n and the elements: ");
    if (scanf("%d", &n) != 1 || n < 1 || n > 20) { printf("Invalid size\n"); return 1; }
    for (i = 0; i < n; i++) scanf("%d", &a[i]);

    for (i = n / 2 - 1; i >= 0; i--)          /* build max-heap */
        heapify(a, n, i);
    for (i = n - 1; i > 0; i--) {             /* move max to the end, shrink heap */
        t = a[0]; a[0] = a[i]; a[i] = t;
        heapify(a, i, 0);
    }

    printf("Heap sorted:");
    for (i = 0; i < n; i++) printf(" %d", a[i]);
    printf("\n");
    return 0;
}

