#define RANGE 100

void counting_sort(int *arr, int n)
{
    int count[RANGE], *p, i, k = 0;
    memset(count, 0, sizeof count);
    for (p = arr; p < arr + n; p++)          /* count each value */
        (*(count + *p))++;
    for (i = 0; i < RANGE; i++)              /* write values back in order */
        while (*(count + i) > 0) {
            *(arr + k++) = i;
            (*(count + i))--;
        }
}

