#include <stdio.h>

/* stable counting sort on the digit given by exp (1, 10, 100, ...) */
void digit_sort(int a[], int n, int exp)
{
    int out[30], count[10] = {0}, i;
    for (i = 0; i < n; i++) count[(a[i] / exp) % 10]++;
    for (i = 1; i < 10; i++) count[i] += count[i - 1];
    for (i = n - 1; i >= 0; i--)
        out[--count[(a[i] / exp) % 10]] = a[i];
    for (i = 0; i < n; i++) a[i] = out[i];
}

