    max = a[0];
    for (i = 1; i < n; i++) if (a[i] > max) max = a[i];

    for (exp = 1; max / exp > 0; exp *= 10) {
        digit_sort(a, n, exp);
        printf("After sorting by digit place %-4d:", exp);
        for (i = 0; i < n; i++) printf(" %d", a[i]);
