struct List {
    int data[30];
    int size;
};

void shell_sort(struct List *l)
{
    int gap, i, j, temp;
    for (gap = l->size / 2; gap > 0; gap /= 2)
        for (i = gap; i < l->size; i++) {
            temp = l->data[i];
            for (j = i; j >= gap && l->data[j - gap] > temp; j -= gap)
                l->data[j] = l->data[j - gap];
            l->data[j] = temp;
        }
}

