#include <stdio.h>

void cocktail(int a[], int n)
{
    int start = 0, end = n - 1, swapped = 1, i, t;
    while (swapped) {
        swapped = 0;
        for (i = start; i < end; i++)            /* forward pass */
            if (a[i] > a[i + 1]) { t = a[i]; a[i] = a[i + 1]; a[i + 1] = t; swapped = 1; }
        end--;
        for (i = end; i > start; i--)            /* backward pass */
            if (a[i] < a[i - 1]) { t = a[i]; a[i] = a[i - 1]; a[i - 1] = t; swapped = 1; }
        start++;
    }
}

