#include <stdio.h>

int bsearch_rec(int a[], int low, int high, int target)
{
    int mid;
    if (low > high) return -1;               /* base case: not found */
    mid = low + (high - low) / 2;
    if (a[mid] == target) return mid;
    if (a[mid] < target) return bsearch_rec(a, mid + 1, high, target);
    return bsearch_rec(a, low, mid - 1, target);
}

