#include <stdio.h>

int jump_search(int a[], int n, int target)
{
    int step = (int)sqrt((double)n), prev = 0, i;
    if (step < 1) step = 1;
    /* jump ahead in blocks until the block may contain the target */
    while (prev < n && a[(prev + step < n ? prev + step : n) - 1] < target)
        prev += step;
    /* linear search inside that block */
    for (i = prev; i < prev + step && i < n; i++)
        if (a[i] == target) return i;
    return -1;
}

