int exponential_search(int a[], int n, int target)
{
    int bound = 1;
    if (a[0] == target) return 0;
    while (bound < n && a[bound] <= target)    /* double the range */
        bound *= 2;
    return binary_range(a, bound / 2, (bound < n ? bound : n - 1), target);
}

