#include <stdio.h>

int ternary_search(int a[], int lo, int hi, int target)
{
    while (lo <= hi) {
        int third = (hi - lo) / 3;
        int m1 = lo + third, m2 = hi - third;
        if (a[m1] == target) return m1;
        if (a[m2] == target) return m2;
        if (target < a[m1]) hi = m1 - 1;             /* first third */
        else if (target > a[m2]) lo = m2 + 1;        /* last third */
        else { lo = m1 + 1; hi = m2 - 1; }           /* middle third */
    }
    return -1;
}

