/* nearly sorted: element i may sit at position i-1, i or i+1 */
int nearly_sorted_search(int a[], int n, int target)
{
    int lo = 0, hi = n - 1, mid;
    while (lo <= hi) {
        mid = lo + (hi - lo) / 2;
        if (a[mid] == target) return mid;
        if (mid > lo && a[mid - 1] == target) return mid - 1;
        if (mid < hi && a[mid + 1] == target) return mid + 1;
        if (a[mid] > target) hi = mid - 2;
        else lo = mid + 2;
    }
    return -1;
}

