#include <stdlib.h>

int closest(int a[], int n, int target)
{
    int lo = 0, hi = n;                       /* lower bound search */
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    if (lo == 0) return a[0];
    if (lo == n) return a[n - 1];
    /* compare the neighbours on either side of the insertion point */
    return (abs(a[lo] - target) < abs(target - a[lo - 1])) ? a[lo] : a[lo - 1];
}

