/* Recursive binary search on a[low..high] */
int search(const int a[], int low, int high, int key)
{
    int mid;
    if (low > high)
        return -1;
    mid = low + (high - low) / 2;
    if (a[mid] == key)
        return mid;
    if (key < a[mid])
        return search(a, low, mid - 1, key);
    return search(a, mid + 1, high, key);
}

