/* First occurrence using binary search: keep searching left after a hit */
int firstOccurrence(const int a[], int n, int key)
{
    int low = 0, high = n - 1, ans = -1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (a[mid] == key) {
            ans = mid;
            high = mid - 1;
        } else if (a[mid] < key)
            low = mid + 1;
        else
            high = mid - 1;
    }
    return ans;
}

