/* Search in rotated sorted array using pointers */
int searchRotated(const int *a, int n, int key)
{
    const int *lo = a, *hi = a + n - 1;
    while (lo <= hi) {
        const int *mid = lo + (hi - lo) / 2;
        if (*mid == key)
            return (int)(mid - a);
        if (*lo <= *mid) {                      /* left half sorted */
            if (key >= *lo && key < *mid) hi = mid - 1;
            else lo = mid + 1;
        } else {                                /* right half sorted */
            if (key > *mid && key <= *hi) lo = mid + 1;
            else hi = mid - 1;
        }
    }
    return -1;
}

