    int value;
};

/* A peak is an element not smaller than its neighbours */
struct Peak findPeak(const int a[], int n)
{
    struct Peak p = {0, a[0]};
    int i;
    for (i = 0; i < n; i++) {
        int leftOk = (i == 0) || (a[i] >= a[i - 1]);
        int rightOk = (i == n - 1) || (a[i] >= a[i + 1]);
        if (leftOk && rightOk) {
            p.index = i;
            p.value = a[i];
            return p;
        }
    }
    return p;
}

