        comparisons++;
        /* linear scan inside the block */
        for (i = prev; i < n && i < cur; i++) {
            comparisons++;
            if (a[i] == key)
                break;
        }
        printf("\n--- Jump Search Result ---\n");
        printf("Block size  : %d\n", step);
