int interpolation(const int a[], int n, int key)
{
    int lo = 0, hi = n - 1;
    while (lo <= hi && key >= a[lo] && key <= a[hi]) {
        int pos;
        if (a[hi] == a[lo])
            return (a[lo] == key) ? lo : -1;
        pos = lo + (int)((long)(key - a[lo]) * (hi - lo) / (a[hi] - a[lo]));
        if (a[pos] == key) return pos;
        if (a[pos] < key) lo = pos + 1;
        else hi = pos - 1;
    }
    return -1;
}

