/* Exponential search: double the range, then binary search inside it */
int exponentialSearch(const int a[], int n, int key)
{
    int bound = 1;
    if (n == 0) return -1;
    if (a[0] == key) return 0;
    while (bound < n && a[bound] < key)
        bound *= 2;
    return binarySearchRange(a, bound / 2, (bound < n ? bound : n - 1), key);
}

