/* Ternary search on a sorted array.
   Time : O(log3 n) loop steps, but about 2 comparisons per step, so it is
          not faster than binary search in practice.
   Space: O(1) because it is iterative. */
int ternarySearch(const int a[], int n, int key)
{
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int third = (hi - lo) / 3;
        int m1 = lo + third;
        int m2 = hi - third;
        if (a[m1] == key) return m1;
        if (a[m2] == key) return m2;
        if (key < a[m1]) hi = m1 - 1;
        else if (key > a[m2]) lo = m2 + 1;
        else { lo = m1 + 1; hi = m2 - 1; }
    }
    return -1;
}

