/* Lower bound = first index whose value is >= target.
   Time : O(log n) - the search range is halved every iteration.
   Space: O(1) - only a few integer variables are used. */
int lowerBound(const int a[], int n, int target)
{
    int lo = 0, hi = n;
    while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (a[mid] < target) lo = mid + 1;
        else hi = mid;
    }
    return lo;
}

