        { 1,  4,  7, 11},
        {12, 15, 18, 21},
        {25, 29, 33, 40}
    };
    int rows = 3, cols = 4, key = 29;
    int lo = 0, hi = rows * cols - 1, found = 0;

    /* Treat the matrix as one sorted list; index k -> row k/cols, col k%cols */
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        int value = m[mid / cols][mid % cols];
        if (value == key) {
            printf("%d found at row %d, column %d\n", key, mid / cols, mid % cols);
            found = 1;
            break;
        }
        if (value < key) lo = mid + 1;
        else hi = mid - 1;
    }
    if (!found)
        printf("%d not found\n", key);
    return 0;
}

#include <stdio.h>

typedef struct {
    int id;
    int value;
} Record;

/* interpolation search on records sorted by value */
int searchRecord(const Record r[], int n, int key)
{
    int lo = 0, hi = n - 1;
    while (lo <= hi && key >= r[lo].value && key <= r[hi].value) {
        int pos;
        if (r[hi].value == r[lo].value)
            return r[lo].value == key ? lo : -1;
        pos = lo + (key - r[lo].value) * (hi - lo) / (r[hi].value - r[lo].value);
        if (r[pos].value == key) return pos;
        if (r[pos].value < key) lo = pos + 1;
        else hi = pos - 1;
    }
    return -1;
}

int main(void)
{
    Record rec[50];
    int n, q, i, key, pos;

    printf("Number of records: ");
    scanf("%d", &n);
    printf("Enter id and value (values ascending):\n");
    for (i = 0; i < n; i++)
        scanf("%d %d", &rec[i].id, &rec[i].value);
    printf("Number of queries: ");
    scanf("%d", &q);
    while (q-- > 0) {
        scanf("%d", &key);
        pos = searchRecord(rec, n, key);
        if (pos < 0) printf("Value %d: not found\n", key);
        else printf("Value %d: record id %d at index %d\n", key, rec[pos].id, pos);
    }
    return 0;
}

