int main(void)
{
    char text[100];
    int len = 0, i, bestStart = 0, bestLen = 1, center;

    printf("Enter a short string: ");
    if (scanf("%99s", text) != 1) return 1;
    while (text[len] != '\0')
        len++;

    /* expand around every possible center (odd and even) */
    for (center = 0; center < 2 * len - 1; center++) {
        int left = center / 2;
        int right = left + center % 2;
        while (left >= 0 && right < len && text[left] == text[right]) {
            left--;
            right++;
        }
        if (right - left - 1 > bestLen) {
            bestLen = right - left - 1;
            bestStart = left + 1;
        }
    }

    printf("Longest palindromic substring: ");
    for (i = bestStart; i < bestStart + bestLen; i++)
        putchar(text[i]);
    printf(" (length %d)\n", bestLen);
    return 0;
}

