    int tests[4] = {121, 1331, 123, 4554};
    int i;
    for (i = 0; i < 4; i++)
    {
        printf("%d is %s\n", tests[i], isPalindrome(tests[i]) ? "a palindrome" : "not a palindrome");
    }
    return 0;
}

int isPalindrome(int n)
{
    int original = n, rev = 0;
    while (n > 0)
    {
        rev = rev * 10 + n % 10;
        n /= 10;
    }
    return rev == original;
}

#include <stdio.h>

int isArmstrong(int n);

int main(void)
{
    int n;
    printf("Armstrong numbers between 100 and 999:\n");
    for (n = 100; n <= 999; n++)
    {
        if (isArmstrong(n))
        {
            printf("%d ", n);
        }
    }
    printf("\n");
    return 0;
}

/* sum of cubes of the digits equals the number (3-digit case) */
int isArmstrong(int n)
{
    int temp = n, sum = 0, digit;
    while (temp > 0)
    {
        digit = temp % 10;
        sum += digit * digit * digit;
        temp /= 10;
    }
    return sum == n;
}

