#define N 3

void addMatrices(int a[N][N], int b[N][N], int result[N][N]);
void printMatrix(int m[N][N]);

int main(void)
{
    int a[N][N] = {{1, 2, 3}, {4, 5, 6}, {7, 8, 9}};
    int b[N][N] = {{9, 8, 7}, {6, 5, 4}, {3, 2, 1}};
    int sum[N][N];
    addMatrices(a, b, sum);
    printf("Sum of the matrices:\n");
    printMatrix(sum);
    return 0;
}

void addMatrices(int a[N][N], int b[N][N], int result[N][N])
{
    int i, j;
    for (i = 0; i < N; i++)
    {
        for (j = 0; j < N; j++)
        {
            result[i][j] = a[i][j] + b[i][j];
        }
    }
}

void printMatrix(int m[N][N])
{
    int i, j;
    for (i = 0; i < N; i++)
    {
        for (j = 0; j < N; j++)
        {
            printf("%4d", m[i][j]);
        }
        printf("\n");
    }
}

