#include <stdio.h>

int *findMax(int arr[], int n);

int main(void)
{
    int data[5] = {8, 41, 17, 63, 29};
    int *p = findMax(data, 5);      /* pointer into the caller's array: safe */
    if (p != NULL)
    {
        printf("Largest value = %d at index %d\n", *p, (int)(p - data));
        *p = 0;                     /* change the element through the pointer */
        printf("After setting it to 0, data[3] = %d\n", data[3]);
    }
    return 0;
}

/* Returns a pointer to the largest element.
   It points into the array owned by the caller, never to a local variable. */
int *findMax(int arr[], int n)
{
    int i;
    int *best = NULL;
    if (n <= 0)
    {
        return NULL;
    }
    best = &arr[0];
    for (i = 1; i < n; i++)
    {
        if (arr[i] > *best)
        {
            best = &arr[i];
        }
    }
    return best;
}

#include <stdio.h>

int sumRecursive(int n);
int sumIterative(int n);

int main(void)
{
    int n = 10;
    printf("Recursive sum of 1..%d = %d\n", n, sumRecursive(n));
    printf("Iterative sum of 1..%d = %d\n", n, sumIterative(n));
    return 0;
}

int sumRecursive(int n)
{
    if (n == 0)                 /* base case */
    {
        return 0;
    }
    return n + sumRecursive(n - 1);
}

int sumIterative(int n)
{
    int sum = 0, i;
    for (i = 1; i <= n; i++)
    {
        sum += i;
    }
    return sum;
}

