#include <stdio.h>

int isPrime(int n);

int main(void)
{
    int n;
    printf("Enter a number: ");
    scanf("%d", &n);
    if (isPrime(n))
    {
        printf("%d is a prime number.\n", n);
    }
    else
    {
        printf("%d is not a prime number.\n", n);
    }
    return 0;
}

/* Returns 1 if n is prime, otherwise 0. */
int isPrime(int n)
{
    int i;
    /* numbers below 2 are never prime */
    if (n < 2)
    {
        return 0;
    }
    /* a composite number has a divisor not greater than its square root,
       so we only test i up to sqrt(n) */
    for (i = 2; i * i <= n; i++)
    {
        if (n % i == 0)
        {
            return 0;   /* found a divisor */
        }
    }
    return 1;           /* no divisor found */
}

#include <stdio.h>

int gcd(int a, int b);

int main(void)
{
    int tests[6][2] = {{0, 5}, {7, 0}, {0, 0}, {-12, 18}, {1, 999}, {36, 36}};
    int i;
    for (i = 0; i < 6; i++)
    {
        int a = tests[i][0], b = tests[i][1];
        if (a == 0 && b == 0)
        {
            printf("GCD(0, 0) is undefined\n");     /* boundary case */
        }
        else
        {
            printf("GCD(%d, %d) = %d\n", a, b, gcd(a, b));
        }
    }
    return 0;
}

/* works with zero and negative values too */
int gcd(int a, int b)
{
    if (a < 0)
    {
        a = -a;
    }
    if (b < 0)
    {
        b = -b;
    }
    while (b != 0)
    {
        int rem = a % b;
        a = b;
        b = rem;
    }
    return a;
}

