    if (isArmstrong(n))
    {
        printf("%d is an Armstrong number.\n", n);
    }
    else
    {
        printf("%d is not an Armstrong number.\n", n);
    }
    return 0;
}

int isArmstrong(int n)
{
    int digits[10];             /* array holding the digits */
    int count = 0, i, j, sum = 0, temp = n;
    if (n <= 0)
    {
        return 0;
    }
    while (temp > 0)
    {
        digits[count++] = temp % 10;
        temp /= 10;
    }
    for (i = 0; i < count; i++)
    {
        int term = 1;
        for (j = 0; j < count; j++)
        {
            term *= digits[i];
        }
        sum += term;            /* digit raised to number of digits */
    }
    return sum == n;
}

