void generate(char buf[], int pos, int open, int close, int n)
{
    if (pos == 2 * n) {
        buf[pos] = '\0';
        printf("%s\n", buf);
        return;
    }
    if (open < n) {
        buf[pos] = '(';
        generate(buf, pos + 1, open + 1, close, n);
    }
    if (close < open) {
        buf[pos] = ')';
        generate(buf, pos + 1, open, close + 1, n);
    }
}

