/* can some subset of the first n elements add up to target? */
int subsetSum(const int a[], int n, int target)
{
    if (target == 0)
        return 1;
    if (n == 0 || target < 0)
        return 0;
    return subsetSum(a, n - 1, target - a[n - 1]) || subsetSum(a, n - 1, target);
}

