/* Main logic: each call peels off the last digit (n % 10) and
   appends it to rev (rev * 10 + digit). When n becomes 0, rev
   holds the digits in reverse order. */
int reverse(int n, int rev)
{
    if (n == 0)
        return rev;
    return reverse(n / 10, rev * 10 + n % 10);
}

