/* a^0 = 1 for any a (including 0^0 treated as 1 here);
   negative exponents give 1/a^|b| */
double power(double a, int b)
{
    if (b == 0)
        return 1.0;
    if (b < 0)
        return 1.0 / power(a, -b);
    return a * power(a, b - 1);
}

