    printf("Enter %d elements in ascending order: ", n);
    readArray(a, n);
    printf("Enter key: ");
    if (scanf("%d", &key) != 1) {
        printf("Invalid key.\n");
        return 1;
    }
    report(a, n, key);
    return 0;
}

