/* Time cost: T(n) = 2*T(n-1) + 1, so 2^n - 1 moves -> O(2^n).
   Space cost: recursion depth is n, so O(n) stack space. */
long long hanoi(int n, char from, char to, char via)
{
    if (n == 0)
        return 0;
    long long moves = hanoi(n - 1, from, via, to);
    printf("Move disk %d from %c to %c\n", n, from, to);
    moves += 1;
    moves += hanoi(n - 1, via, to, from);
    return moves;
}

int main(void)
{
