    printf("Enter number of disks (1-10): ");
    if (scanf("%d", &n) != 1 || n < 1 || n > 10) {
        printf("Invalid number of disks.\n");
        return 1;
    }
    long long moves = hanoi(n, 'A', 'C', 'B');
    printf("Moves made: %lld (expected 2^%d - 1 = %d)\n", moves, n, (1 << n) - 1);
    return 0;
}

