#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void)
{
    size_t capacity = 10;
    const char *text = "Hello, dynamic world";
    char *buffer = (char *)malloc(capacity);

    if (buffer == NULL)
    {
        printf("Allocation failed\n");
        return 1;
    }
    /* bounds checking: copy at most capacity - 1 characters */
    if (strlen(text) >= capacity)
    {
        printf("Text has %zu characters, buffer holds only %zu; truncating\n", strlen(text), capacity - 1);
    }
    strncpy(buffer, text, capacity - 1);
    buffer[capacity - 1] = '\0';
    printf("Buffer contains: \"%s\"\n", buffer);
    free(buffer);
    return 0;
}

