#include <stdio.h>

/* Bubble sort using only pointer parameters */
void sort(int *start, int *end)
{
    for (int *i = start; i < end - 1; i++)
        for (int *j = start; j < end - 1 - (i - start); j++)
            if (*j > *(j + 1)) {
                int t = *j;
                *j = *(j + 1);
                *(j + 1) = t;
            }
}

int main(void)
{
    int a[] = {29, 5, 17, 3, 41, 12, 8};
    int n = sizeof(a) / sizeof(a[0]);

    printf("Before:");
    for (int *p = a; p < a + n; p++) printf(" %d", *p);
    sort(a, a + n);
    printf("\nAfter :");
    for (int *p = a; p < a + n; p++) printf(" %d", *p);
    printf("\n");
    return 0;
}

