#include <stdio.h>

/* Copy n bytes from src to dst */
void copy_bytes(void *dst, const void *src, size_t n)
{
    unsigned char *d = dst;
    const unsigned char *s = src;
    while (n--)
        *d++ = *s++;
}

int main(void)
{
    int src[4] = {10, 20, 30, 40};
    int dst[4] = {0};

    copy_bytes(dst, src, sizeof(src));
    printf("Copied %zu bytes\n", sizeof(src));
    for (int i = 0; i < 4; i++)
        printf("dst[%d] = %d\n", i, dst[i]);
    return 0;
}

