#include <stdio.h>

long sum(const int *p, int n)
{
    long total = 0;
    if (p == NULL || n <= 0)    /* boundary cases */
        return 0;
    while (n--)
        total += *p++;
    return total;
}

int main(void)
{
    int a[] = {5, 10, 15, 20};
    int one[] = {42};

    printf("Normal array  : %ld\n", sum(a, 4));
    printf("Single element: %ld\n", sum(one, 1));
    printf("Empty (n = 0) : %ld\n", sum(a, 0));
    printf("NULL pointer  : %ld\n", sum(NULL, 3));
    return 0;
}

