#include <stdio.h>

double add(double a, double b) { return a + b; }
double sub(double a, double b) { return a - b; }
double mul(double a, double b) { return a * b; }
double divide(double a, double b) { return a / b; }

int main(void)
{
    double x, y;
    char op;
    double (*fn)(double, double) = NULL;

    printf("Enter: number number operator(+ - * /): ");
    if (scanf("%lf %lf %c", &x, &y, &op) != 3) {
        printf("Error: invalid input\n");
        return 1;
    }
    switch (op) {
        case '+': fn = add; break;
        case '-': fn = sub; break;
        case '*': fn = mul; break;
        case '/':
            if (y == 0) { printf("Error: division by zero\n"); return 1; }
            fn = divide;
            break;
        default:
            printf("Error: unknown operator '%c'\n", op);
            return 1;
    }
    printf("%.2f %c %.2f = %.2f\n", x, op, y, fn(x, y));
    return 0;
}

