#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int cap = 2, count = 0, v;
    int *a = malloc(cap * sizeof(int));
    if (a == NULL) return 1;

    printf("Enter numbers (0 to stop): ");
    while (scanf("%d", &v) == 1 && v != 0) {
        if (count == cap) {                 /* full: double capacity */
            cap *= 2;
            int *t = realloc(a, cap * sizeof(int));
            if (t == NULL) { free(a); return 1; }
            a = t;
            printf("[array grown to %d]\n", cap);
        }
        a[count++] = v;
    }
    printf("Stored %d values:", count);
    for (int i = 0; i < count; i++) printf(" %d", a[i]);
    printf("\n");
    free(a);
    return 0;
}

