/* Returns 0 on success, -1 on error; never leaks memory */
int process(int n)
{
    int *a = NULL, *b = NULL;
    int status = -1;

    a = malloc(n * sizeof(int));
    if (a == NULL) goto cleanup;
    b = malloc(n * sizeof(int));
    if (b == NULL) goto cleanup;

    for (int i = 0; i < n; i++) { a[i] = i; b[i] = a[i] * 2; }
    printf("b[%d] = %d\n", n - 1, b[n - 1]);
    status = 0;

cleanup:                                    /* single exit frees everything */
    free(a);
    free(b);
    return status;
}

