/* Reads a whole line of any length; caller must free the result */
char *read_line(void)
{
    size_t cap = 8, len = 0;
    char *buf = malloc(cap);
    if (buf == NULL) return NULL;
    buf[0] = '\0';

    while (fgets(buf + len, (int)(cap - len), stdin) != NULL) {
        len += strlen(buf + len);
        if (len > 0 && buf[len - 1] == '\n') {
            buf[len - 1] = '\0';
            return buf;
        }
        cap *= 2;
        char *t = realloc(buf, cap);
        if (t == NULL) { free(buf); return NULL; }
        buf = t;
    }
    return buf;
}

