        for (int *p = jag[i]; p < jag[i] + lens[i]; p++)
            *p = (int)(p - jag[i]) + 1 + i * 10;
    }
    printf("Jagged array:\n");
    for (int i = 0; i < rows; i++) {
        printf("Row %d (length %d):", i, lens[i]);
        for (int j = 0; j < lens[i]; j++)
            printf(" %d", *(*(jag + i) + j));
        printf("\n");
    }
    for (int i = 0; i < rows; i++)
        free(jag[i]);
    free(jag);
    free(lens);
    return 0;
}

