struct Node {
    int data;
    struct Node *next;
};

int main(void)
{
    struct Node *head = NULL, *tail = NULL;
    for (int i = 1; i <= 5; i++) {              /* create 5 nodes */
        struct Node *n = malloc(sizeof(struct Node));
        if (n == NULL)
            return 1;
        n->data = i * i;
        n->next = NULL;
        if (head == NULL)
            head = tail = n;
        else {
            tail->next = n;
            tail = n;
        }
    }
    printf("List: ");
    for (struct Node *p = head; p != NULL; p = p->next)
        printf("%d -> ", p->data);
    printf("NULL\n");

    int freed = 0;
    while (head != NULL) {                      /* free every node */
        struct Node *next = head->next;
        free(head);
        head = next;
        freed++;
    }
    printf("Freed %d nodes\n", freed);
    return 0;
}

