#include <stdio.h>
#include <stdlib.h>

/* Safe helper: free and set pointer to NULL */
void safe_free(int **p)
{
    free(*p);
    *p = NULL;
}

int main(void)
{
    int *p = malloc(sizeof(int));
    if (p == NULL)
        return 1;
    *p = 77;
    printf("Before free: *p = %d\n", *p);
    free(p);
    /* UNSAFE: p is now dangling. Reading *p here is undefined behaviour,
       so we do NOT do it. */
    printf("After free : p is dangling, must not be used\n");

    int *q = malloc(sizeof(int));
    if (q == NULL)
        return 1;
    *q = 88;
    safe_free(&q);
    if (q == NULL)
        printf("Safe way   : q set to NULL, check before use -> not used\n");
    safe_free(&q);                       /* freeing NULL is harmless */
    printf("Freeing NULL again is harmless.\n");
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void)
{
    int cap = 2, n = 0, v;
    int *a = malloc(cap * sizeof *a);
    if (a == NULL)
        return 1;
    while (scanf("%d", &v) == 1) {
        if (n == cap) {
            /* Doubling makes appends O(1) on average: copying costs O(n)
               only occasionally. Space used is at most 2x the data. */
            int *tmp = realloc(a, 2 * cap * sizeof *a);
            if (tmp == NULL) {          /* a is still valid, so no leak */
                printf("realloc failed\n");
                free(a);
                return 1;
            }
            a = tmp;
            cap *= 2;
        }
        a[n++] = v;
    }
    printf("Read %d values, capacity %d\n", n, cap);
    for (int i = 0; i < n; i++)
        printf("%d ", a[i]);
    printf("\n");
    free(a);
    return 0;
}

