#include <stdio.h>
#include <stdlib.h>

struct Buffer {
    char *data;
    size_t len, cap;
};

/* Append one character, doubling the capacity when full */
int append(struct Buffer *b, char c)
{
    if (b->len + 1 >= b->cap) {
        size_t newCap = b->cap * 2;
        char *tmp = realloc(b->data, newCap);
        if (tmp == NULL)
            return 0;
        b->data = tmp;
        b->cap = newCap;
    }
    b->data[b->len++] = c;
    b->data[b->len] = '\0';
    return 1;
}

int main(void)
{
    struct Buffer buf = {malloc(4), 0, 4};     /* no global variables */
    if (buf.data == NULL)
        return 1;
    buf.data[0] = '\0';
    const char *msg = "Expanding buffers are useful!";
    for (const char *p = msg; *p; p++)
        if (!append(&buf, *p)) {
            free(buf.data);
            return 1;
        }
    printf("Text     : %s\n", buf.data);
    printf("Length   : %zu\n", buf.len);
    printf("Capacity : %zu\n", buf.cap);
    free(buf.data);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

/* Allocate two blocks; if the second "fails", release the first. */
int build(int n, int simulateFail)
{
    int *a = malloc(n * sizeof(int));
    if (a == NULL)
        return -1;
    int *b = simulateFail ? NULL : malloc(n * sizeof(int));
    if (b == NULL) {
        printf("  second allocation failed, freeing first block\n");
        free(a);                      /* avoids a leak on the error path */
        return -1;
    }
    for (int i = 0; i < n; i++) {
        a[i] = i;
        b[i] = i * i;
    }
    int sum = 0;
    for (int i = 0; i < n; i++)
        sum += a[i] + b[i];
    free(b);
    free(a);
    return sum;
}

int main(void)
{
    int n;
    printf("Enter n: ");
    if (scanf("%d", &n) != 1 || n <= 0) {
        printf("Invalid n\n");
        return 1;
    }
    for (int fail = 0; fail <= 1; fail++) {
        printf("Run %d (simulate failure = %d)\n", fail + 1, fail);
        int r = build(n, fail);
        if (r < 0)
            printf("  build() reported an error\n");
        else
            printf("  build() result = %d\n", r);
    }
    return 0;
}

