#define LIMIT 100000            /* pretend the system has only 100000 bytes */

/* Wrapper that returns NULL when the request exceeds LIMIT */
void *limited_alloc(size_t size)
{
    if (size > LIMIT)
        return NULL;
    return malloc(size);
}

int main(void)
{
    size_t size = 1000;
    for (int step = 1; step <= 6; step++) {      /* loop: grow request x10 */
        char *p = limited_alloc(size);
        if (p == NULL) {
            printf("Step %d: %zu bytes -> allocation FAILED, stopping\n", step, size);
            break;
        }
        p[0] = 'x';
        printf("Step %d: %zu bytes -> allocated\n", step, size);
        free(p);
        size *= 10;
    }
    return 0;
}

