#include <stdio.h>

struct Date
{
    int day, month, year;
};

/* returns -1 if a is earlier, 0 if equal, 1 if a is later */
int compareDates(struct Date a, struct Date b)
{
    if (a.year != b.year)
        return a.year < b.year ? -1 : 1;
    if (a.month != b.month)
        return a.month < b.month ? -1 : 1;
    if (a.day != b.day)
        return a.day < b.day ? -1 : 1;
    return 0;
}

int main(void)
{
    struct Date d1 = {12, 3, 2024}, d2 = {25, 12, 2023};
    int r = compareDates(d1, d2);

    printf("Date 1: %02d/%02d/%d\n", d1.day, d1.month, d1.year);
    printf("Date 2: %02d/%02d/%d\n", d2.day, d2.month, d2.year);
    if (r == 0)
        printf("Both dates are equal.\n");
    else if (r < 0)
        printf("Date 1 is earlier.\n");
    else
        printf("Date 1 is later.\n");
    return 0;
}

