    return r.length * r.width;
}

int main(void)
{
    struct Rect r = {8, 5};
    int result;

    printf("Before call: length=%d width=%d\n", r.length, r.width);
    result = area(r);
    printf("Function returned (using modified copy): %d\n", result);
    printf("After call : length=%d width=%d (original unchanged)\n", r.length, r.width);
    return 0;
}

