#include <stdio.h>

struct Student {
    int roll;
    char name[15];
};

int main(void)
{
    struct Student s[5] = {
        {42, "Kavya"}, {7, "Omar"}, {19, "Lena"}, {3, "Ivan"}, {25, "Zara"}
    };
    int n = 5;

    printf("Before sorting:\n");
    for (int i = 0; i < n; i++)
        printf("  %2d %s\n", s[i].roll, s[i].name);

    /* Bubble sort: repeatedly swap neighbours that are out of order */
    for (int pass = 0; pass < n - 1; pass++) {
        for (int j = 0; j < n - 1 - pass; j++) {
            if (s[j].roll > s[j + 1].roll) {
                struct Student tmp = s[j];       /* swap whole records */
                s[j] = s[j + 1];
                s[j + 1] = tmp;
            }
        }
    }

    printf("After sorting by roll number:\n");
    for (int i = 0; i < n; i++)
        printf("  %2d %s\n", s[i].roll, s[i].name);
    return 0;
}

