        struct Complex a, b, sum;
        printf("Pair %d (re1 im1 re2 im2): ", i);
        scanf("%lf %lf %lf %lf", &a.re, &a.im, &b.re, &b.im);
        sum.re = a.re + b.re;
        sum.im = a.im + b.im;
        printf("  (%.1f%+.1fi) + (%.1f%+.1fi) = %.1f%+.1fi\n",
               a.re, a.im, b.re, b.im, sum.re, sum.im);
    }
    return 0;
}

#include <stdio.h>

struct Complex {
    double re, im;
};

/* (a+bi)(c+di) = (ac-bd) + (ad+bc)i, result stored through pointer */
void multiply(const struct Complex *x, const struct Complex *y, struct Complex *out)
{
    out->re = x->re * y->re - x->im * y->im;
    out->im = x->re * y->im + x->im * y->re;
}

int main(void)
{
    struct Complex a, b, prod;
    printf("Enter first complex number (re im): ");
    scanf("%lf %lf", &a.re, &a.im);
    printf("Enter second complex number (re im): ");
    scanf("%lf %lf", &b.re, &b.im);
    multiply(&a, &b, &prod);
    printf("(%.1f%+.1fi) * (%.1f%+.1fi) = %.1f%+.1fi\n",
           a.re, a.im, b.re, b.im, prod.re, prod.im);
    return 0;
}

