#include <stdio.h>

struct Rectangle {
    double length, width;
};

/* Receives a COPY of the structure; changes do not affect the caller */
double area(struct Rectangle r)
{
    double a = r.length * r.width;
    r.length = 0;                        /* modifies only the copy */
    return a;
}

int main(void)
{
    struct Rectangle rect = {12.5, 4.0};
    printf("Before call : length = %.1f, width = %.1f\n", rect.length, rect.width);
    double a = area(rect);
    printf("Area        : %.2f\n", a);
    printf("After call  : length = %.1f, width = %.1f (unchanged)\n", rect.length, rect.width);
    return 0;
}

#include <stdio.h>

struct Product {
    char name[20];
    int stock;
    double price;
};

/* Apply a percentage discount through a pointer; returns 0 if invalid */
int discount(struct Product *p, double percent)
{
    if (p == NULL || percent < 0 || percent > 100)
        return 0;
    p->price -= p->price * percent / 100.0;
    return 1;
}

int main(void)
{
    struct Product item = {"Headphones", 25, 1999.00};
    double pct;
    printf("%s: price %.2f, stock %d\n", item.name, item.price, item.stock);
    printf("Enter discount percent (0-100): ");
    if (scanf("%lf", &pct) != 1) {
        printf("Error: not a number\n");
        return 1;
    }
    if (!discount(&item, pct)) {
        printf("Error: discount must be between 0 and 100\n");
        return 1;
    }
    printf("New price after %.1f%% off: %.2f\n", pct, item.price);
    return 0;
}

