            fwrite(&s, sizeof s, 1, fp);
            printf("Record %d updated.\n", id);
            break;
        }
    }
    rewind(fp);
    printf("\nAll records now:\n");
    while (fread(&s, sizeof s, 1, fp) == 1)
        printf("%d %-6s %.1f\n", s.id, s.name, s.marks);
