    fseek(fp, 4, SEEK_SET);                 /* jump to 5th character */
    ch = fgetc(fp);
    printf("After fseek(4): char = %c, ftell = %ld\n", ch, ftell(fp));

    fseek(fp, -2, SEEK_END);                /* 2 bytes before the end */
