{
    int ch;
    FILE *in = fopen("low994.txt", "w");
    if (in == NULL) return 1;
    fputs("loops save typing.\nvery useful, really!\n", in);
    fclose(in);

    in = fopen("low994.txt", "r");
    FILE *out = fopen("up994.txt", "w");
    if (in == NULL || out == NULL) return 1;
    while ((ch = fgetc(in)) != EOF)         /* one loop handles every character */
        fputc(toupper(ch), out);
    fclose(in);
    fclose(out);

    out = fopen("up994.txt", "r");
    if (out == NULL) return 1;
    printf("Converted file:\n");
    while ((ch = fgetc(out)) != EOF)
        putchar(ch);
    fclose(out);
    remove("low994.txt");
    remove("up994.txt");
    return 0;
}

#include <stdio.h>
#include <ctype.h>

int main(void)
{
    char line[100];
    char *p;
    int vowels = 0, consonants = 0;
    FILE *fp = fopen("vc995.txt", "w");
    if (fp == NULL) return 1;
    fputs("Pointers walk through strings.\nEvery character is checked.\n", fp);
    fclose(fp);

    fp = fopen("vc995.txt", "r");
    if (fp == NULL) return 1;
    while (fgets(line, sizeof line, fp) != NULL)
    {
        for (p = line; *p != '\0'; p++)     /* move pointer along the line */
        {
            if (isalpha((unsigned char)*p))
            {
                switch (tolower((unsigned char)*p))
                {
                    case 'a': case 'e': case 'i': case 'o': case 'u':
                        vowels++;
                        break;
                    default:
                        consonants++;
                }
            }
        }
    }
    fclose(fp);

    printf("Vowels: %d, Consonants: %d\n", vowels, consonants);
    remove("vc995.txt");
    return 0;
}

#include <stdio.h>
#include <string.h>

#define MAX_LINES 20

int main(void)
{
    char lines[MAX_LINES][80];              /* array holding the file lines */
    char word[30], buf[80];
    int n = 0, i, matches = 0;
    FILE *fp = fopen("search996.txt", "w");
    if (fp == NULL) return 1;
    fputs("Arrays store many values.\nStrings are arrays of char.\nFiles keep data safe.\n", fp);
    fclose(fp);

    printf("Enter word to search: ");
    if (scanf("%29s", word) != 1) return 1;

    fp = fopen("search996.txt", "r");
    if (fp == NULL) return 1;
    while (n < MAX_LINES && fgets(buf, sizeof buf, fp) != NULL)
    {
        buf[strcspn(buf, "\n")] = '\0';
        strcpy(lines[n++], buf);
    }
    fclose(fp);

    for (i = 0; i < n; i++)
        if (strstr(lines[i], word) != NULL)
        {
            printf("Line %d: %s\n", i + 1, lines[i]);
            matches++;
        }
    printf("Lines containing \"%s\": %d\n", word, matches);
    remove("search996.txt");
    return 0;
}

#include <stdio.h>
#include <string.h>

/* structure bundling the replacement request */
struct Replacement
{
    char oldWord[20];
    char newWord[20];
    int count;
};

int main(void)
{
    struct Replacement r = {"is", "was", 0};
    char line[200];
    FILE *fp = fopen("doc997.txt", "w");
    if (fp == NULL) return 1;
    fputs("This is a test. It is simple.\nWhat is next?\n", fp);
    fclose(fp);

    fp = fopen("doc997.txt", "r");
    FILE *tmp = fopen("tmp997.txt", "w");
    if (fp == NULL || tmp == NULL) return 1;
    while (fgets(line, sizeof line, fp) != NULL)
    {
        char *p = line, *f;
        while ((f = strstr(p, r.oldWord)) != NULL)
        {
            fprintf(tmp, "%.*s%s", (int)(f - p), p, r.newWord);
            p = f + strlen(r.oldWord);
            r.count++;
        }
        fputs(p, tmp);
    }
    fclose(fp);
    fclose(tmp);
    remove("doc997.txt");
    rename("tmp997.txt", "doc997.txt");

    printf("Replaced \"%s\" with \"%s\" %d times.\n", r.oldWord, r.newWord, r.count);
    fp = fopen("doc997.txt", "r");
    if (fp == NULL) return 1;
    while (fgets(line, sizeof line, fp) != NULL)
        printf("%s", line);
    fclose(fp);
    remove("doc997.txt");
    return 0;
}

#include <stdio.h>

struct Student
{
    int roll;
    char name[30];
    float marks;
};

int main(void)
{
    int n, i;
    struct Student s;
    printf("How many students? ");
    if (scanf("%d", &n) != 1 || n < 1)
    {
        printf("Invalid count.\n");
        return 1;
    }

    FILE *fp = fopen("stud998.txt", "w");
    if (fp == NULL) return 1;
    for (i = 1; i <= n; i++)                /* process many records in a loop */
    {
        printf("Student %d (roll name marks): ", i);
        if (scanf("%d %29s %f", &s.roll, s.name, &s.marks) != 3)
        {
            printf("Bad record, stopping.\n");
            break;
        }
        fprintf(fp, "%d %s %.1f\n", s.roll, s.name, s.marks);
    }
    fclose(fp);

    fp = fopen("stud998.txt", "r");
    if (fp == NULL) return 1;
    int saved = 0;
    printf("\nStored records:\n");
    while (fscanf(fp, "%d %29s %f", &s.roll, s.name, &s.marks) == 3)
    {
        printf("%d %s %.1f\n", s.roll, s.name, s.marks);
        saved++;
    }
    fclose(fp);
    printf("Total saved: %d\n", saved);
    remove("stud998.txt");
    return 0;
}

#include <stdio.h>

struct Student
{
    int roll;
    char name[30];
    float marks;
};

int main(void)
{
    struct Student s;
    int count = 0;
    float total = 0;
    FILE *fp = fopen("stud999.txt", "w");
    if (fp == NULL) return 1;
    fprintf(fp, "101 Asha 88.5\n102 Ravi 74.0\n103 Meena 93.25\n104 Kiran 61.5\n");
    fclose(fp);

    fp = fopen("stud999.txt", "r");
    if (fp == NULL)
    {
        printf("Cannot open file.\n");
        return 1;
    }
    printf("+------+------------+--------+\n");
    printf("| Roll | Name       | Marks  |\n");
    printf("+------+------------+--------+\n");
    while (fscanf(fp, "%d %29s %f", &s.roll, s.name, &s.marks) == 3)
    {
        printf("| %4d | %-10s | %6.2f |\n", s.roll, s.name, s.marks);
        total += s.marks;
        count++;
    }
    printf("+------+------------+--------+\n");
    fclose(fp);
    printf("Students: %d   Average marks: %.2f\n", count, count ? total / count : 0.0);
    remove("stud999.txt");
    return 0;
}

#include <stdio.h>

struct Student
{
    int id;
    char name[20];
    float marks;
};

int main(void)
{
    int n, i, saved = 0;
    struct Student s;
    printf("How many records (1-5)? ");
    if (scanf("%d", &n) != 1 || n < 1 || n > 5)
    {
        printf("Error: count must be a number from 1 to 5.\n");
        return 1;
    }

    FILE *fp = fopen("stud1000.dat", "wb");
    if (fp == NULL) return 1;
    for (i = 1; i <= n; i++)
    {
        printf("Record %d (id name marks): ", i);
        if (scanf("%d %19s %f", &s.id, s.name, &s.marks) != 3)
        {
            printf("Error: wrong input format. Stopping.\n");
            break;
        }
        if (s.id <= 0 || s.marks < 0 || s.marks > 100)   /* validate before writing */
        {
            printf("Error: invalid id or marks, record skipped.\n");
            continue;
        }
        fwrite(&s, sizeof s, 1, fp);
        saved++;
    }
    fclose(fp);
    printf("\n%d record(s) written to binary file.\n", saved);

    fp = fopen("stud1000.dat", "rb");
    if (fp == NULL) return 1;
    while (fread(&s, sizeof s, 1, fp) == 1)
        printf("%d %s %.1f\n", s.id, s.name, s.marks);
    fclose(fp);
    remove("stud1000.dat");
    return 0;
}
